/**
 * The scopes some tool of this app's MCP server needs (#541).
 *
 * They are the scopes of MCP browser sign-in: what the authorization server publishes, what the consent screen
 * offers and what a connection can be granted (`mcpOAuthResourceScopes`). An entity kept out of MCP (`patterns`,
 * by default) and an operation an override excludes have no tool, and so no permission. For hand-written tools
 * it is what the overrides declare (`extraToolScopes`).
 *
 * The list is data, generated by `nextspark prepare` (`@nextsparkjs/registries/mcp-scopes`, from
 * scripts/build/registry/generators/mcp-scopes.mjs): the entity configs and the `entities/<slug>/mcp.ts` files are
 * read as source and the rules of `../exposure` are applied to what they say. This module is in the import graph
 * of `lib/auth`, which every route of the app reaches, so it loads neither the entity registry (the config of
 * every entity, which core keeps out of the per-entity routes: tests/node/core-routes.test.ts) nor the registry of
 * overrides (every `mcp.ts` of the project, tool code included, which would then run whenever auth loads).
 *
 * A project that mounts its own MCP route with other `excludeSlugs`, `defaultOperations` or `utilityTools` exposes
 * something else than this list says: the default route is the one this follows.
 */
import { MCP_SCOPES } from '@nextsparkjs/registries/mcp-scopes'
import type { EntityConfig } from '../../entities/types'
import { toolScopesOf } from '../exposure'
import type { McpEntityOverride } from '../types'

/** Sorted. Fixed when the registries are generated. */
export function mcpToolScopes(): string[] {
  return [...MCP_SCOPES.toolScopes]
}

/** The entities the API serves, the ones a scope can name. Sorted, fixed when the registries are generated. */
export function mcpApiEntities(): string[] {
  return [...MCP_SCOPES.apiEntities]
}

/**
 * How the generated lists differ from what the registries of the running app say, one line per difference; none
 * when they agree.
 *
 * For the `/api/mcp` route, which has both registries loaded anyway: the generated lists come from reading the
 * sources, and this is the check that the reading said what the code does. A difference is safe in both directions
 * (a scope no tool needs does nothing, a tool whose scope is not in the list cannot be called through a browser
 * sign-in connection), and it means the registries are stale or a config is built in a way the reader cannot see.
 */
export function mcpScopeDrift(entities: Record<string, EntityConfig>, overrides: Record<string, McpEntityOverride>): string[] {
  const differences: string[] = []
  const compare = (what: string, generated: readonly string[], running: readonly string[]) => {
    const missing = running.filter(item => !generated.includes(item))
    const extra = generated.filter(item => !running.includes(item))
    if (missing.length) differences.push(`${what}: the app has ${missing.join(', ')}, the generated list does not`)
    if (extra.length) differences.push(`${what}: the generated list has ${extra.join(', ')}, the app does not`)
  }
  compare('tool scopes', MCP_SCOPES.toolScopes, toolScopesOf(entities, { overrides }))
  compare(
    'API entities',
    MCP_SCOPES.apiEntities,
    [...new Set(Object.values(entities).filter(config => config?.access?.api && config.slug).map(config => config.slug))]
  )
  return differences
}
